   const query=linked?"SELECT s.endpoint,s.subscription_json,d.linked_at,u.email,u.first_name,u.last_name FROM push_subscriptions s LEFT JOIN push_user_devices d ON d.endpoint=s.endpoint LEFT JOIN app_users u ON u.id=d.user_id ORDER BY d.linked_at DESC LIMIT 500":"SELECT endpoint,subscription_json,NULL AS linked_at,NULL AS email,NULL AS first_name,NULL AS last_name FROM push_subscriptions ORDER BY endpoint LIMIT 500";
   const rows=await env.DB.prepare(query).all();
   const names=new Map();const devices=(rows.results||[]).map((x,i)=>{let language='';try{language=JSON.parse(x.subscription_json).language||''}catch{};const fullName=[x.first_name,x.last_name].map(v=>String(v||'').trim()).filter(Boolean).join(' '),owner=fullName||String(x.email||'').trim();const count=(names.get(owner)||0)+1;if(owner)names.set(owner,count);return {label:owner?owner+' · Gerät '+count:'Nicht zugeordnet · Gerät '+(i+1),email:x.email||null,language,linked_at:x.email?x.linked_at:null}});
